try {
  helpers.log('WhatsApp - Send Message: Starting execution');

  const accessToken = node.properties.credential.value;
  const phoneNumberId = node.properties.phoneNumberId.value;
  const to = node.properties.recipientPhone.value;
  const messageText = node.properties.message.value;
  const previewUrl = node.properties.previewUrl.value || false;

  if (!accessToken || !phoneNumberId || !to || !messageText) {
    helpers.error('Missing required fields');
    throw new Error('Access Token, Phone Number ID, Recipient and Message are required');
  }

  helpers.log('Sending to:', to);

  const endpoint = `https://graph.facebook.com/v18.0/${phoneNumberId}/messages`;
  const payload = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: to,
    type: 'text',
    text: {
      preview_url: previewUrl,
      body: messageText
    }
  };

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  const result = await response.json();

  if (!response.ok) {
    const errorMsg = result.error?.message || JSON.stringify(result);
    helpers.error('WhatsApp API Error:', errorMsg);
    throw new Error(`WhatsApp API Error: ${errorMsg}`);
  }

  helpers.log('Message sent successfully. ID:', result.messages?.[0]?.id);

  return {
    ...data,
    messageId: result.messages?.[0]?.id,
    whatsapp: result
  };

} catch (error) {
  helpers.error('Execution failed:', error.message);
  throw error;
}
